=== Views/blogFrontPage.cshtml
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = "_Layout";
    ViewData["Title"] = Model.Title;
    var posts = Model.Children<BlogPost>()?.OrderByDescending(p => p.PublishDate).ToList() ?? new List<BlogPost>();
}

<section class="mb-10">
    <h1 class="text-4xl font-bold tracking-tight text-slate-900">@Model.Title</h1>
    @if (!string.IsNullOrWhiteSpace(Model.Intro))
    {
        <p class="mt-3 text-lg text-slate-600">@Model.Intro</p>
    }
</section>

<section class="mb-12">
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
</section>

<section>
    <h2 class="mb-6 text-2xl font-semibold text-slate-900">Latest posts</h2>
    <ul class="grid gap-6 sm:grid-cols-2">
        @foreach (var post in posts)
        {
            var imageUrl = post.ListingImage?.GetCropUrl(width: 800, height: 450);
            <li class="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:shadow-md">
                <a href="@post.Url()" class="block">
                    @if (!string.IsNullOrEmpty(imageUrl))
                    {
                        <img src="@imageUrl" alt="@post.ListingImage?.Name" class="aspect-video w-full object-cover" loading="lazy" />
                    }
                    <div class="p-5">
                        <p class="text-xs uppercase tracking-wide text-slate-500">@post.PublishDate.ToString("d MMMM yyyy")</p>
                        <h3 class="mt-1 text-xl font-semibold text-indigo-700">@post.Title</h3>
                        <p class="mt-2 text-slate-600">@post.Excerpt</p>
                    </div>
                </a>
            </li>
        }
    </ul>
</section>
=== Views/blogPost.cshtml
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogPost>
@{
    Layout = "_Layout";
    ViewData["Title"] = Model.Title;
    var heroUrl = Model.ListingImage?.GetCropUrl(width: 1200, height: 500);
    var homeUrl = Model.AncestorOrSelf<BlogFrontPage>()?.Url() ?? "/";
}

<article>
    <a href="@homeUrl" class="text-sm text-indigo-700 hover:underline">&larr; All posts</a>
    <header class="mt-4 mb-8">
        <p class="text-xs uppercase tracking-wide text-slate-500">@Model.PublishDate.ToString("d MMMM yyyy")</p>
        <h1 class="mt-1 text-4xl font-bold tracking-tight text-slate-900">@Model.Title</h1>
        @if (!string.IsNullOrWhiteSpace(Model.Excerpt))
        {
            <p class="mt-3 text-lg text-slate-600">@Model.Excerpt</p>
        }
    </header>
    @if (!string.IsNullOrEmpty(heroUrl))
    {
        <img src="@heroUrl" alt="@Model.ListingImage?.Name" class="mb-8 aspect-[12/5] w-full rounded-xl object-cover" />
    }
    @await Html.GetBlockGridHtmlAsync(Model, "blocks")
</article>
=== Views/Shared/_Layout.cshtml
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@{
    var pageTitle = ViewData["Title"] as string;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>@pageTitle</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</head>
<body class="bg-slate-50 text-slate-800 antialiased">
    <header class="border-b border-slate-200 bg-white">
        <div class="mx-auto flex max-w-4xl items-center justify-between px-6 py-4">
            <a href="/" class="text-lg font-bold tracking-tight text-indigo-700">The MCP Blog</a>
            <span class="text-sm text-slate-500">Notes on the Model Context Protocol</span>
        </div>
    </header>
    <main class="mx-auto max-w-4xl px-6 py-10">
        @RenderBody()
    </main>
    <footer class="border-t border-slate-200 py-6 text-center text-sm text-slate-500">
        Built with Umbraco and MCP.
    </footer>
</body>
</html>
